"""Typed results with JSON and standalone HTML export."""
from __future__ import annotations

from dataclasses import asdict, dataclass, field, is_dataclass
from html import escape
import json
from pathlib import Path
from typing import Any

import numpy as np

DISCLAIMER = (
    "SpectralAudit performs signal-based forensic analysis. Its findings do not "
    "constitute proof that a recording was generated by artificial intelligence."
)


def _json_default(value: Any) -> Any:
    if is_dataclass(value) and not isinstance(value, type):
        return asdict(value)
    if isinstance(value, np.ndarray):
        return value.tolist()
    if isinstance(value, np.generic):
        return value.item()
    if isinstance(value, Path):
        return str(value)
    raise TypeError(f"Cannot serialize {type(value).__name__}")


@dataclass
class AuditReport:
    """Conservative observations, without an inferred AI origin probability."""

    metadata: dict[str, Any]
    findings: dict[str, Any]
    limitations: list[str] = field(default_factory=list)
    interpretation: str = "Origin inconclusive: spectral characteristics do not establish provenance."
    version: str = "0.1.0"

    def as_dict(self) -> dict[str, Any]:
        return asdict(self)

    def to_json(self, path: str | Path) -> Path:
        target = Path(path)
        target.write_text(json.dumps(self.as_dict(), indent=2, default=_json_default, allow_nan=False), encoding="utf-8")
        return target

    def to_html(self, path: str | Path) -> Path:
        """Write a portable HTML report with readable structured measurements."""
        target = Path(path)
        pretty = json.dumps(self.as_dict(), indent=2, default=_json_default, allow_nan=False)
        payload = escape(pretty)
        figure = ""
        # Drawing is optional and never mutates the analyzed audio.
        try:
            if "sha256" in self.metadata and Path(self.metadata["path"]).is_file():
                from .audio import load_audio
                from .plotting import spectral_svg
                wave = load_audio(self.metadata["path"])
                if wave.metadata["sha256"] == self.metadata["sha256"]:
                    figure = spectral_svg(wave.mono, wave.rate)
        except (OSError, ValueError, KeyError):
            figure = ""
        target.write_text(
            "<!doctype html><html lang='en'><meta charset='utf-8'>"
            "<meta name='viewport' content='width=device-width,initial-scale=1'>"
            "<title>SpectralAudit report</title><style>body{max-width:960px;"
            "margin:3rem auto;padding:0 1rem;font:16px system-ui;line-height:1.5}"
            "pre{overflow:auto;background:#101923;color:#e4f3ef;padding:1.2rem;border-radius:9px}"
            "small{color:#666}</style><h1>SpectralAudit report</h1>"
            f"<p>{escape(self.interpretation)}</p><p><strong>{escape(DISCLAIMER)}</strong></p>"
            f"{figure}<pre>{payload}</pre><small>Reproducible measurements; no origin classification.</small></html>",
            encoding="utf-8",
        )
        return target


@dataclass
class MasterComparison:
    metadata: dict[str, Any]
    spectral_changes: dict[str, Any]
    new_artifacts: list[dict[str, Any]]
    limitations: list[str]
    interpretation: str = "Differences observed; no causal or generative-origin attribution."

    def to_json(self, path: str | Path) -> Path:
        target = Path(path)
        target.write_text(json.dumps(asdict(self), indent=2, default=_json_default, allow_nan=False), encoding="utf-8")
        return target

    def to_html(self, path: str | Path) -> Path:
        return AuditReport(self.metadata, {"comparison": asdict(self)}, self.limitations, self.interpretation).to_html(path)
